mapper.select:
select channel, delivery_state as deliveryState, count(1) as receiptCount
from official_broadcast_log where broadcast_id = #{broadcastId}
group by channel, delivery_state order by channel, delivery_state

mapper.update:
update official_broadcast_log set clicked = 1
where broadcast_id = #{broadcastId} and member_id = #{memberId} and channel = #{channel}
  and reached = 1 and delivery_state in ('SUCCESS', 'INAPP_STORED')
